'\''1i /* draw horizontal separator line at screen row, from x for w columns */
static void vi_draw_hsep(int row, int x, int w)
{
	term_pos(row, x);
	for (int i = 0; i < w; i++)
		term_chr('\''-'\'');
}

/* draw vertical separator line at screen column */
static void vi_draw_vsep(int col, int y, int h)
{
	for (int i = 0; i < h; i++) {
		term_pos(y + i, col);
		term_chr('\''|'\'');
	}
}

