+/* windows tiling the same band as curwin along axis, sorted; 0 if they leave holes */
+static int win_group(struct win **grp, int axis)
+{
+	struct win *w = wins;
+	int i, j, n = 0;
+	do {
+		if (win_pos(w, !axis) == win_pos(curwin, !axis) &&
+				win_len(w, !axis) == win_len(curwin, !axis))
+			grp[n++] = w;
+		w = w->next;
+	} while (w != wins);
+	for (i = 0; i < n - 1; i++)
+		for (j = i + 1; j < n; j++)
+			if (win_pos(grp[j], axis) < win_pos(grp[i], axis)) {
+				w = grp[i];
+				grp[i] = grp[j];
+				grp[j] = w;
+			}
+	for (i = 0; i < n - 1; i++)
+		if (win_pos(grp[i], axis) + win_len(grp[i], axis) + 1 !=
+				win_pos(grp[i+1], axis))
+			return 0;
+	return n;
+}
+
+static void *ec_split(char *loc, char *cmd, char *arg)
+{
+	return win_split(*cmd != 'v', arg);	/* vs splits the horizontal axis */
+}
+
+static void *ec_equalize(char *loc, char *cmd, char *arg)
+{
+	struct win **grp;
+	int axis, i, n, pos, len, extra;
+	if (nwins <= 1)
+		return NULL;
+	grp = emalloc(nwins * sizeof(grp[0]));
+	for (axis = 0; axis < 2; axis++) {
+		if ((n = win_group(grp, axis)) < 2)
+			continue;
+		len = win_pos(grp[n-1], axis) + win_len(grp[n-1], axis)
+			- win_pos(grp[0], axis) - (n - 1);
+		extra = len % n;
+		len /= n;
+		pos = win_pos(grp[0], axis);
+		for (i = 0; i < n; i++) {
+			win_pos(grp[i], axis) = pos;
+			win_len(grp[i], axis) = len + (i < extra);
+			pos += win_len(grp[i], axis) + 1;	/* +1 separator */
+		}
+		break;
+	}
+	free(grp);
+	return NULL;
+}
+
