+/* window management functions */
+static void win_full(struct win *w)
+{
+	w->y = 0;
+	w->x = 0;
+	w->h = xrows;
+	w->w = xcols;
+}
+
+void win_init(void)
+{
+	if (wins)
+		return;
+	wins = emalloc(sizeof(struct win));
+	memset(wins, 0, sizeof(struct win));
+	wins->buf = ex_buf;
+	wins->next = wins;		/* circular list */
+	win_full(wins);
+	curwin = wins;
+	nwins = 1;
+}
+
+/* the globals hold the state of curwin; these two sync it both ways */
+void win_save(void)
+{
+	curwin->row = xrow;
+	curwin->off = xoff;
+	curwin->top = xtop;
+	curwin->left = xleft;
+	curwin->buf = ex_buf;
+	ex_buf->td = xtd;	/* win_load() reads td back from the buffer */
+}
+
+static void win_load(void)
+{
+	if (curwin->buf != ex_buf) {
+		exbuf_save(ex_buf)
+		ex_buf = curwin->buf;
+		xtd = ex_buf->td;
+		syn_setft(xb_ft);
+	}
+	xrow = curwin->row;
+	xoff = curwin->off;
+	xtop = curwin->top;
+	xleft = curwin->left;
+}
+
+/* rescale a layout made for orows x ocols to the current terminal size */
+void win_size(int orows, int ocols)
+{
+	struct win *w = wins;
+	if (nwins == 1) {
+		win_full(wins);
+		return;
+	}
+	do {	/* edges scale, not sizes, so that neighbours stay glued */
+		int x2 = w->x + w->w == ocols ? xcols : (w->x + w->w) * xcols / ocols;
+		int y2 = w->y + w->h == orows ? xrows : (w->y + w->h) * xrows / orows;
+		w->x = w->x * xcols / ocols;
+		w->y = w->y * xrows / orows;
+		w->w = MAX(1, x2 - w->x);
+		w->h = MAX(1, y2 - w->y);
+		w = w->next;
+	} while (w != wins);
+}
+
+void win_switch(struct win *w)
+{
+	if (w && w != curwin) {
+		win_save();
+		curwin = w;
+		win_load();
+	}
+}
+
+/* expand w over closing, if the two are adjacent along axis */
+static int win_absorb(struct win *w, struct win *closing, int axis)
+{
+	if (win_pos(w, !axis) != win_pos(closing, !axis) ||
+			win_len(w, !axis) != win_len(closing, !axis))
+		return 0;
+	if (win_pos(w, axis) + win_len(w, axis) + 1 != win_pos(closing, axis) &&
+			win_pos(closing, axis) + win_len(closing, axis) + 1 !=
+			win_pos(w, axis))
+		return 0;
+	win_pos(w, axis) = MIN(win_pos(w, axis), win_pos(closing, axis));
+	win_len(w, axis) += win_len(closing, axis) + 1;
+	return 1;
+}
+
+void win_close(void)
+{
+	struct win *w = wins, *prev = curwin, *closing = curwin;
+	if (nwins <= 1)
+		return;
+	while (prev->next != closing)
+		prev = prev->next;
+	do {	/* hand the freed space to an adjacent window */
+		if (w != closing && (win_absorb(w, closing, 0) ||
+					win_absorb(w, closing, 1)))
+			break;
+		w = w->next;
+	} while (w != wins);
+	prev->next = closing->next;
+	if (wins == closing)
+		wins = closing->next;
+	curwin = prev->next;
+	free(closing);
+	if (--nwins == 1)
+		win_full(wins);
+	win_load();
+}
+
+/* split curwin along axis, optionally opening arg in the new window */
+void *win_split(int axis, char *arg)
+{
+	struct win *w;
+	int len;
+	if (curwin->h < 4 || curwin->w < 10)
+		return "window too small";
+	win_save();
+	w = emalloc(sizeof(struct win));
+	*w = *curwin;			/* same buffer, cursor and scroll state */
+	len = win_len(curwin, axis) / 2;
+	win_len(curwin, axis) = len;
+	win_pos(w, axis) += len + 1;	/* +1 for the separator */
+	win_len(w, axis) -= len + 1;
+	if (arg && *arg) {
+		struct buf *obuf = ex_buf;
+		int i = bufs_find(arg, strlen(arg));
+		if (i >= 0)
+			w->buf = &bufs[i];
+		else {
+			bufs_switch(bufs_open(arg, strlen(arg)));
+			w->buf = ex_buf;
+			if ((i = open(xb_path, O_RDONLY)) >= 0) {
+				lbuf_rd(xb, i, 0, lbuf_len(xb));
+				close(i);
+			}
+			ex_bufpostfix(ex_buf, arg[0]);
+			ex_buf = obuf;		/* curwin keeps its own buffer */
+			exbuf_load(ex_buf)
+			syn_setft(xb_ft);
+		}
+		w->row = w->off = w->top = w->left = 0;
+	}
+	w->next = curwin->next;
+	curwin->next = w;
+	nwins++;
+	return NULL;
+}
