+/* draw the separators owned by each window: its right and bottom edge */
+static void vi_draw_separators(void)
+{
+	struct win *w = wins;
+	do {
+		if (w->x + w->w < xcols)
+			vi_draw_vsep(w->x + w->w, w->y, w->h);
+		if (w->y + w->h < xrows)
+			vi_draw_hsep(w->y + w->h, w->x, w->w);
+		w = w->next;
+	} while (w != wins);
+}
+
+/* draw all windows and separators */
+static void vi_draw_allwins(void)
+{
+	struct win *w = wins, *cur = curwin;
+	preserve(struct buf*, ex_buf,)
+	preserve(int, xrow,)
+	preserve(int, xoff,)
+	preserve(int, xtop,)
+	preserve(int, xleft,)
+	preserve(int, xtd,)
+	do {
+		curwin = w;
+		xrow = w->row;
+		xoff = w->off;
+		xtop = w->top;
+		xleft = w->left;
+		if (w->buf != ex_buf) {
+			ex_buf = w->buf;
+			xtd = ex_buf->td;
+			syn_setft(xb_ft);
+		}
+		syn_scdir(0);
+		for (int i = xtop; i < xtop + w->h; i++)
+			vi_drawrow(i);
+		w = w->next;
+	} while (w != wins);
+	vi_draw_separators();
+	curwin = cur;
+	restore(xrow)
+	restore(xoff)
+	restore(xtop)
+	restore(xleft)
+	restore(xtd)
+	if (ex_buf != tmpex_buf) {
+		restore(ex_buf)
+		syn_setft(xb_ft);
+	}
+}
+
+/* redraw the current window, or every window when the screen is split */
+static void vi_redraw(void)
+{
+	if (nwins > 1)
+		vi_draw_allwins();
+	else
+		vi_drawagain(xtop);
+}
